// Copies the Swagger UI static assets into public/ so Vercel serves them from
// its CDN. @nestjs/swagger reads them from node_modules at runtime, which
// Vercel's file tracing cannot follow. swagger-ui-init.js is generated by Nest
// at runtime and is intentionally not copied.
import { copyFileSync, mkdirSync } from 'node:fs';
import { createRequire } from 'node:module';
import { join } from 'node:path';

// Resolve swagger-ui-dist through @nestjs/swagger so the exact version it uses is copied.
const require = createRequire(import.meta.url);
const nestSwaggerRequire = createRequire(require.resolve('@nestjs/swagger'));
const assetsDir = nestSwaggerRequire('swagger-ui-dist/absolute-path.js')();

// Read by src/main.ts via customSwaggerUiPath.
const outDir = join(import.meta.dirname, '../swagger-ui');
const files = [
  'swagger-ui.css',
  'swagger-ui-bundle.js',
  'swagger-ui-standalone-preset.js',
  'favicon-16x16.png',
  'favicon-32x32.png',
];

mkdirSync(outDir, { recursive: true });
for (const file of files) copyFileSync(join(assetsDir, file), join(outDir, file));
console.log(`Copied ${files.length} Swagger UI assets to swagger-ui/`);
